/**
 * AI Quiz Maker  -  Fill-in-the-Gap Dropdown Question Type
 * Inline dropdowns within sentence flow
 * 
 * Rules:
 * - Sentence with inline gaps
 * - Each gap renders a dropdown
 * - Options generated by AI
 * - Dropdowns match text baseline
 * - No layout jump when opened
 * 
 * @module     mod_aiquiz/questions/gap_dropdown
 * @copyright  2025 NCT
 * @license    http://www.gnu.org/copyleft/gpl.html GNU GPL v3 or later
 */

define('mod_aiquiz/questions/gap_dropdown', [
    'mod_aiquiz/core/animations',
    'mod_aiquiz/core/state'
], function(Animations, State) {
    'use strict';

    function GapDropdown(options) {
        this.element = null;
        this.answers = {};
        this.revealed = false;

        this.options = Object.assign({
            questionId: '',
            questionText: '',
            sentence: '',
            gaps: [],
            shuffleOptions: true
        }, options);

        this.onChange = null;
    }

    GapDropdown.prototype.render = function() {
        var container = document.createElement('div');
        container.className = 'aiq-question aiq-question--gap-dropdown';
        container.setAttribute('data-question-id', this.options.questionId);

        if (this.options.questionText) {
            var questionText = document.createElement('h2');
            questionText.className = 'aiq-question__text';
            questionText.innerHTML = this.options.questionText;
            container.appendChild(questionText);
        }

        var sentenceEl = document.createElement('div');
        sentenceEl.className = 'aiq-gap-sentence';

        var sentenceHtml = this.buildSentence();
        sentenceEl.innerHTML = sentenceHtml;

        this.bindDropdowns(sentenceEl);

        container.appendChild(sentenceEl);

        this.element = container;

        Animations.fadeInUp(sentenceEl);

        return container;
    };

    GapDropdown.prototype.buildSentence = function() {
        var self = this;
        var html = this.options.sentence;

        this.options.gaps.forEach(function(gap, index) {
            var placeholder = '{{gap' + index + '}}';
            var dropdownHtml = self.createDropdownHtml(gap, index);
            html = html.replace(placeholder, dropdownHtml);
        });

        return html;
    };

    GapDropdown.prototype.createDropdownHtml = function(gap, index) {
        var options = gap.options.slice();
        if (this.options.shuffleOptions) {
            options = this.shuffleArray(options);
        }

        var html = '<span class="aiq-gap-dropdown-wrapper">';
        html += '<select class="aiq-gap-dropdown" data-gap-id="' + gap.id + '" data-gap-index="' + index + '">';
        html += '<option value="">Select...</option>';

        options.forEach(function(opt) {
            html += '<option value="' + opt.id + '">' + opt.text + '</option>';
        });

        html += '</select>';
        html += '<span class="aiq-gap-indicator"></span>';
        html += '</span>';

        return html;
    };

    GapDropdown.prototype.shuffleArray = function(arr) {
        var shuffled = arr.slice();
        for (var i = shuffled.length - 1; i > 0; i--) {
            var j = Math.floor(Math.random() * (i + 1));
            var temp = shuffled[i];
            shuffled[i] = shuffled[j];
            shuffled[j] = temp;
        }
        return shuffled;
    };

    GapDropdown.prototype.bindDropdowns = function(container) {
        var self = this;
        var dropdowns = container.querySelectorAll('.aiq-gap-dropdown');

        dropdowns.forEach(function(dropdown) {
            dropdown.addEventListener('change', function() {
                var gapId = dropdown.getAttribute('data-gap-id');
                var value = dropdown.value;

                if (value) {
                    self.answers[gapId] = value;
                    dropdown.parentElement.classList.add('aiq-gap-dropdown-wrapper--selected');
                } else {
                    delete self.answers[gapId];
                    dropdown.parentElement.classList.remove('aiq-gap-dropdown-wrapper--selected');
                }

                self.updateState();
            });
        });
    };

    GapDropdown.prototype.updateState = function() {
        State.setAnswer(this.options.questionId, Object.assign({}, this.answers));

        if (this.onChange) {
            this.onChange(this.options.questionId, this.answers);
        }
    };

    GapDropdown.prototype.reveal = function(animate) {
        var self = this;
        this.revealed = true;
        var promises = [];

        var dropdowns = this.element.querySelectorAll('.aiq-gap-dropdown');

        dropdowns.forEach(function(dropdown) {
            var gapId = dropdown.getAttribute('data-gap-id');
            var gap = self.options.gaps.find(function(g) { return g.id === gapId; });
            var userAnswer = self.answers[gapId];
            var isCorrect = userAnswer === gap.correctId;

            dropdown.disabled = true;

            var wrapper = dropdown.parentElement;

            if (isCorrect) {
                wrapper.classList.add('aiq-gap-dropdown-wrapper--correct');
                if (animate) {
                    promises.push(Animations.pulse(wrapper));
                }
            } else {
                wrapper.classList.add('aiq-gap-dropdown-wrapper--incorrect');

                var correctOpt = gap.options.find(function(o) { return o.id === gap.correctId; });
                if (correctOpt) {
                    var correction = document.createElement('span');
                    correction.className = 'aiq-gap-correction';
                    correction.textContent = correctOpt.text;
                    wrapper.appendChild(correction);
                }

                if (animate) {
                    promises.push(Animations.shake(wrapper));
                }
            }
        });

        return Promise.all(promises);
    };

    GapDropdown.prototype.getAnswer = function() {
        return Object.assign({}, this.answers);
    };

    GapDropdown.prototype.setAnswer = function(answers) {
        var self = this;
        if (!answers) return;

        Object.keys(answers).forEach(function(gapId) {
            self.answers[gapId] = answers[gapId];

            var dropdown = self.element.querySelector('[data-gap-id="' + gapId + '"]');
            if (dropdown) {
                dropdown.value = answers[gapId];
                dropdown.parentElement.classList.add('aiq-gap-dropdown-wrapper--selected');
            }
        });
    };

    GapDropdown.prototype.isAnswered = function() {
        return Object.keys(this.answers).length === this.options.gaps.length;
    };

    /**
     * Check if all gaps are correctly filled
     * @returns {boolean}
     */
    GapDropdown.prototype.isCorrect = function() {
        var self = this;
        
        if (!this.isAnswered()) {
            return false;
        }
        
        var allCorrect = true;
        this.options.gaps.forEach(function(gap) {
            if (self.answers[gap.id] !== gap.correctId) {
                allCorrect = false;
            }
        });
        
        return allCorrect;
    };

    GapDropdown.prototype.getScore = function() {
        var self = this;
        var correct = 0;
        var total = this.options.gaps.length;

        this.options.gaps.forEach(function(gap) {
            if (self.answers[gap.id] === gap.correctId) {
                correct++;
            }
        });

        return {
            correct: correct,
            total: total,
            percentage: total > 0 ? Math.round((correct / total) * 100) : 0
        };
    };

    GapDropdown.prototype.reset = function() {
        this.revealed = false;
        this.answers = {};

        var dropdowns = this.element.querySelectorAll('.aiq-gap-dropdown');
        dropdowns.forEach(function(dropdown) {
            dropdown.value = '';
            dropdown.disabled = false;

            var wrapper = dropdown.parentElement;
            wrapper.classList.remove(
                'aiq-gap-dropdown-wrapper--selected',
                'aiq-gap-dropdown-wrapper--correct',
                'aiq-gap-dropdown-wrapper--incorrect'
            );

            var correction = wrapper.querySelector('.aiq-gap-correction');
            if (correction) {
                wrapper.removeChild(correction);
            }
        });
    };

    GapDropdown.prototype.destroy = function() {
        if (this.element && this.element.parentNode) {
            this.element.parentNode.removeChild(this.element);
        }
        this.element = null;
    };

    return GapDropdown;
});
